```nginx
daemon off;
worker_processes 1;
pid @ROOT@/nginx.pid;
error_log @ROOT@/error.log;
events { worker_connections 64; }
http {
 access_log off;
 client_body_temp_path @ROOT@/client_body;
 proxy_temp_path @ROOT@/proxy_temp;
 fastcgi_temp_path @ROOT@/fastcgi_temp;
 uwsgi_temp_path @ROOT@/uwsgi_temp;
 scgi_temp_path @ROOT@/scgi_temp;
 map $http_origin $cors_origin { default ""; "https://app.example" $http_origin; "https://admin.example" $http_origin; }
map $http_origin $cors_reject { default 1; "" 0; "https://app.example" 0; "https://admin.example" 0; }
map $cors_origin $cors_credentials { default "true"; "" ""; }
server { listen 127.0.0.1:@PORT@;
 location /api/ {
  add_header Access-Control-Allow-Origin $cors_origin always;
  add_header Access-Control-Allow-Credentials $cors_credentials always;
  add_header Access-Control-Allow-Methods "GET, POST, OPTIONS" always;
  add_header Access-Control-Allow-Headers "Authorization, Content-Type" always;
  add_header Vary Origin always;
  if ($cors_reject) { return 403; }
  if ($request_method = OPTIONS) { return 204; }
  proxy_pass http://127.0.0.1:@UPSTREAM@;
 }
 location / { return 404; }
}
}
```

仅https://app.example与https://admin.example允许跨域携带凭据，响应Access-Control-Allow-Origin必须精确回显白名单Origin且Credentials=true、Vary含Origin；不可用星号。合法OPTIONS返回204并声明GET/POST/OPTIONS和Authorization/Content-Type，不请求源站。恶意近似域名或其他scheme返回403且不请求源站；无Origin普通请求仍正常，但不输出Allow-Origin或Credentials。这里验收服务端CORS契约，不替代浏览器同源策略或业务认证。

原理补充：
浏览器对凭据跨域响应有严格源匹配规则，通配符不能代替明确允许源。按允许列表生成响应并设置恰当Vary，覆盖预检与实际请求；CORS不是服务端身份认证或访问控制的替代。

